interface Data {course?:{label:string;heading:string;active:number};takeawayHighlight?:string;variant?:'course'|'split';featureMessage?:string;featureCaption?:string;kind:string;section:string;title:string;subtitle?:string;items?:Item[];takeaway?:string;takeawayLabel?:string;badge?:string;logos?:string[];nav?:string[];panels?:Item[];steps?:Item[];assurances?:Item[];months?:string[];tracks?:Item[];stages?:Item[];users?:Item[];access?:string[];systems?:{title:string;groups:Item[]}[];exchange?:string;common?:Item;integrations?:{title:string;groups:Item[]}[]}
