  <div v-if="data.takeaway" class="takeaway" data-fit><strong v-if="data.takeawayLabel">{{data.takeawayLabel}}</strong><EmphasisText :text="data.takeaway" :highlight="data.takeawayHighlight" tone="inverse"/></div>
